import{_ as e,o as d,c as a,a3 as s}from"./chunks/framework.BmGVitc1.js";const k=JSON.parse('{"title":"🧮 FK / IK 运动学计算","description":"","frontmatter":{"title":"🧮 FK / IK 运动学计算","outline":[2,4]},"headers":[],"relativePath":"api/kinematics.md","filePath":"api/kinematics.md","lastUpdated":1788858789000}'),i={name:"api/kinematics.md"};function o(n,t,r,c,l,p){return d(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="🧮-fk-ik-运动学计算" tabindex="-1">🧮 FK / IK 运动学计算 <a class="header-anchor" href="#🧮-fk-ik-运动学计算" aria-label="Permalink to &quot;🧮 FK / IK 运动学计算&quot;">​</a></h1><p><a href="/rokae_ws/ROS2_INTERFACE_REFERENCE">查看完整来源文档</a></p><p>运动学服务分别提供左臂和右臂接口：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/aide/upperlimb/fk/left_arm</span></span>
<span class="line"><span>/aide/upperlimb/fk/right_arm</span></span>
<span class="line"><span>/aide/upperlimb/ik/left_arm</span></span>
<span class="line"><span>/aide/upperlimb/ik/right_arm</span></span></code></pre></div><p>服务使用 xCoreSDK <code>xMateModel&lt;7&gt;</code> 和控制器当前 <code>toolset</code>。位姿是 TCP 相对当前 外部参考坐标系的结果。服务只计算，不自动上电，也不发送运动指令；但需要驱动 已连接对应机器人，以读取机型模型和活动工具/工件坐标配置。</p><h2 id="_18-1-forwardkinematics" tabindex="-1">18.1 ForwardKinematics <a class="header-anchor" href="#_18-1-forwardkinematics" aria-label="Permalink to &quot;18.1 ForwardKinematics&quot;">​</a></h2><p>类型：<code>rokae_interfaces/srv/ForwardKinematics</code>。</p><table tabindex="0"><thead><tr><th>方向</th><th>字段</th><th>类型</th><th>单位/说明</th></tr></thead><tbody><tr><td>请求</td><td><code>joints</code></td><td><code>float64[7]</code></td><td>J1…J7，rad</td></tr><tr><td>响应</td><td><code>success</code></td><td><code>bool</code></td><td>SDK 计算是否成功</td></tr><tr><td>响应</td><td><code>message</code></td><td><code>string</code></td><td>结果或错误原因</td></tr><tr><td>响应</td><td><code>pose</code></td><td><code>geometry_msgs/Pose</code></td><td>TCP 位姿，位置 m、姿态四元数</td></tr><tr><td>响应</td><td><code>elbow</code></td><td><code>float64</code></td><td>七轴臂角，rad</td></tr><tr><td>响应</td><td><code>has_elbow</code></td><td><code>bool</code></td><td>臂角是否有效</td></tr><tr><td>响应</td><td><code>configuration</code></td><td><code>int32[]</code></td><td>SDK 关节构型数据</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /aide/upperlimb/fk/left_arm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  rokae_interfaces/srv/ForwardKinematics</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;{joints: [J1, J2, J3, J4, J5, J6, J7]}&quot;</span></span></code></pre></div><h2 id="_18-2-inversekinematics" tabindex="-1">18.2 InverseKinematics <a class="header-anchor" href="#_18-2-inversekinematics" aria-label="Permalink to &quot;18.2 InverseKinematics&quot;">​</a></h2><p>类型：<code>rokae_interfaces/srv/InverseKinematics</code>。</p><table tabindex="0"><thead><tr><th>方向</th><th>字段</th><th>类型</th><th>单位/说明</th></tr></thead><tbody><tr><td>请求</td><td><code>pose</code></td><td><code>geometry_msgs/Pose</code></td><td>TCP 目标，外部参考系</td></tr><tr><td>请求</td><td><code>use_elbow</code></td><td><code>bool</code></td><td>是否使用指定臂角约束七轴选解</td></tr><tr><td>请求</td><td><code>elbow</code></td><td><code>float64</code></td><td>指定臂角，rad</td></tr><tr><td>响应</td><td><code>joints</code></td><td><code>float64[7]</code></td><td>IK 结果，rad</td></tr><tr><td>响应</td><td><code>solved_pose</code></td><td><code>geometry_msgs/Pose</code></td><td>IK 结果经 FK 回算的位姿</td></tr><tr><td>响应</td><td><code>position_error_m</code></td><td><code>float64</code></td><td>FK 回算位置误差，m</td></tr><tr><td>响应</td><td><code>orientation_error_rad</code></td><td><code>float64</code></td><td>FK 回算姿态误差，rad</td></tr><tr><td>响应</td><td><code>success/message</code></td><td><code>bool/string</code></td><td>校验结果或错误原因</td></tr></tbody></table><p>IK 返回前会用同一个模型和 <code>toolset</code> 执行 FK 回算；误差超过 11.10 节配置的 阈值时返回失败。七轴机械臂通常存在多组逆解，因此输出关节角不保证与生成目标 位姿时使用的原始关节角完全相同。</p><h2 id="_18-3-python-联合测试" tabindex="-1">18.3 Python 联合测试 <a class="header-anchor" href="#_18-3-python-联合测试" aria-label="Permalink to &quot;18.3 Python 联合测试&quot;">​</a></h2><p>测试程序先执行 FK，再把输出位姿传给 IK，最后对 IK 结果再次执行 FK：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/ros/humble/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/niic/rokae_ws/install/local_setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/niic/rokae_ws/src/test/test_fk_ik.py</span></span></code></pre></div><p>程序顶部使用 <code>ARM_TYPE=1</code> 选择左臂，<code>ARM_TYPE=2</code> 选择右臂。测试不会上电或 控制机械臂运动。</p>`,17)])])}const m=e(i,[["render",o]]);export{k as __pageData,m as default};
